    args+=(-H "Authorization: ${ELASTICSEARCH_AUTH}")
  fi
  local response status
  response="$(curl "${args[@]}")"
  status="${response##*$'\n'}"
  if [ "$status" -lt 200 ] || [ "$status" -ge 300 ]; then
    echo "error: PUT ${path} failed with HTTP ${status}" >&2
    exit 1
  fi
}

health_check() {
  local body
  body="$(curl -sS "${ELASTICSEARCH_URL}/_cluster/health" 2>/dev/null)" || return 1
  case "$body" in
    *'"status":"green"'*|*'"status":"yellow"'*) ;;
    *) return 1 ;;
  esac
  if [ -n "${KIBANA_URL:-}" ]; then
    body="$(curl -sS "${KIBANA_URL}/api/status" 2>/dev/null)" || return 1
    case "$body" in
      *'"overall":{"level":"available"'*) ;;
      *) return 1 ;;
    esac
  fi
  return 0
}

wait_healthy() {
  local deadline=$(( $(date +%s) + 30 ))
  while :; do
    if health_check; then
      return 0
    fi
    if [ "$(date +%s)" -ge "$deadline" ]; then
