  fi
  local response status
  response="$(curl "${args[@]}")"
  status="${response##*$'\n'}"
  if [ "$status" -lt 200 ] || [ "$status" -ge 300 ]; then
    echo "error: POST ${path} failed with HTTP ${status}" >&2
    exit 1
  fi
}

import_kibana() {
  local ndjson="$1"
  local args=(-sS -w '\n%{http_code}' -X POST "${KIBANA_URL}/api/saved_objects/_import?overwrite=true" -H 'kbn-xsrf: true' --form 'file=@-;filename=import.ndjson;type=application/ndjson')
