    args+=(-H "Authorization: ${ELASTICSEARCH_AUTH}")
  fi
  local response status body
  response="$(printf '%s' "$ndjson" | curl "${args[@]}")"
  status="${response##*$'\n'}"
  body="${response%$'\n'*}"
